// Adds Book Shelf's Android pieces to the project generated by `npx cap add android`:
// "Open with" / "Share" support, file saving, self-updates, version number and signing.
// Usage: node scripts/patch-android.js <versionName> <versionCode>
const fs = require('fs');
const path = require('path');
const root = path.join(__dirname, '..');
const [version = '1.0.0', code = '1'] = process.argv.slice(2);
const app = path.join(root, 'android', 'app');
const javaDir = path.join(app, 'src', 'main', 'java', 'com', 'usama', 'bookshelf');
const must = (cond, msg) => { if (!cond) { console.error('patch-android: ' + msg); process.exit(1); } };

// 1. Java sources
must(fs.existsSync(javaDir), 'Java folder not found: ' + javaDir);
for (const f of ['MainActivity.java', 'BookShelfNative.java'])
  fs.copyFileSync(path.join(root, 'android-native', f), path.join(javaDir, f));

// 2. Manifest: open-with and share filters, install permission
const manPath = path.join(app, 'src', 'main', 'AndroidManifest.xml');
let man = fs.readFileSync(manPath, 'utf8');
const mimes = ['application/pdf', 'application/epub+zip',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  'application/vnd.ms-excel'];
const data = mimes.map(m => `<data android:mimeType="${m}" />`).join('\n                ');
const filters = `
            <intent-filter>
                <action android:name="android.intent.action.VIEW" />
                <category android:name="android.intent.category.DEFAULT" />
                <category android:name="android.intent.category.BROWSABLE" />
                <data android:scheme="content" />
                <data android:scheme="file" />
                ${data}
            </intent-filter>
            <intent-filter>
                <action android:name="android.intent.action.SEND" />
                <category android:name="android.intent.category.DEFAULT" />
                ${data}
            </intent-filter>
`;
const actIdx = man.indexOf('android:name=".MainActivity"');
must(actIdx > 0, 'MainActivity not found in manifest');
const endAct = man.indexOf('</activity>', actIdx);
man = man.slice(0, endAct) + filters + '        ' + man.slice(endAct);
if (!man.includes('REQUEST_INSTALL_PACKAGES'))
  man = man.replace('</manifest>', '    <uses-permission android:name="android.permission.REQUEST_INSTALL_PACKAGES" />\n</manifest>');
fs.writeFileSync(manPath, man);

// 3. File provider paths (used to hand the downloaded update to Android's installer)
const xmlDir = path.join(app, 'src', 'main', 'res', 'xml');
fs.mkdirSync(xmlDir, { recursive: true });
fs.writeFileSync(path.join(xmlDir, 'file_paths.xml'), `<?xml version="1.0" encoding="utf-8"?>
<paths xmlns:android="http://schemas.android.com/apk/res/android">
    <external-path name="my_images" path="." />
    <cache-path name="my_cache_images" path="." />
    <files-path name="my_files" path="." />
</paths>
`);

// 4. Version and signing
const gPath = path.join(app, 'build.gradle');
let g = fs.readFileSync(gPath, 'utf8');
g = g.replace(/versionCode\s+\d+/, `versionCode ${parseInt(code, 10)}`).replace(/versionName\s+"[^"]*"/, `versionName "${version}"`);
must(g.includes(`versionName "${version}"`), 'could not set versionName');
g = g.replace(/android\s*\{/, `android {
    signingConfigs {
        release {
            storeFile file("../../android-signing/bookshelf.keystore")
            storePassword "bookshelf-2026"
            keyAlias "bookshelf"
            keyPassword "bookshelf-2026"
        }
    }`);
g = g.replace(/release\s*\{(\s*)minifyEnabled/, (m, sp) => `release {${sp}signingConfig signingConfigs.release${sp}minifyEnabled`);
must(g.includes('signingConfig signingConfigs.release'), 'could not add signing to the release build');
fs.writeFileSync(gPath, g);
console.log(`Android project patched: version ${version} (${code})`);
